Assume RV32 (32-bit `mcause`). What does this program print?

```c
#include <stdint.h>
#include <stdio.h>
static void decode(uint32_t mcause) {
    uint32_t code = mcause & 0x7FFFFFFFu;
    printf("%s %u\n", (mcause >> 31) ? "interrupt" : "exception", (unsigned)code);
}
int main(void) {
    decode(0x80000007u);
    decode(0x00000002u);
    return 0;
}
```

On a little-endian Cortex-M with 32-bit `int`, what does this program print?

```c
#include <stdint.h>
#include <stdio.h>
int main(void) {
    uint32_t v = 0x12345678u;
    const uint8_t *p = (const uint8_t *)&v;
    printf("%02x %02x %02x %02x\n", p[0], p[1], p[2], p[3]);
    return 0;
}
```

`buf` may point at any address. What can go wrong with the first function on a Cortex-M0+, and why does the second fix it?

```c
#include <stdint.h>
#include <string.h>
uint32_t read_a(const uint8_t *buf) {
    return *(const uint32_t *)buf;
}
uint32_t read_b(const uint8_t *buf) {
    uint32_t v;
    memcpy(&v, buf, sizeof v);
    return v;
}
```

On a 32-bit target, what does this program print? (A device manual lists these registers at offsets `0x00`, `0x04`, ... in this order.)

```c
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
typedef struct {
    volatile uint32_t MODER, OTYPER, OSPEEDR, PUPDR, IDR, ODR, BSRR;
} GPIO_t;
int main(void) {
    printf("%zu %zu\n", offsetof(GPIO_t, ODR), offsetof(GPIO_t, BSRR));
    return 0;
}
```

On an STM32F407 with an $8\,\mathrm{MHz}$ crystal, `RCC_PLLCFGR` fields are: PLLM bits 5:0, PLLN bits 14:6, PLLP bits 17:16 (`00` means divide by 2), PLLSRC bit 22 (1 means crystal), PLLQ bits 27:24. What does this program print: the SYSCLK in Hz and the PLLQ output in Hz?

```c
#include <stdint.h>
#include <stdio.h>
int main(void) {
    uint32_t cfg = (8u << 0) | (336u << 6) | (0u << 16) | (1u << 22) | (7u << 24);
    uint32_t m = cfg & 0x3Fu, n = (cfg >> 6) & 0x1FFu;
    uint32_t p = 2u * (((cfg >> 16) & 3u) + 1u), q = (cfg >> 24) & 0xFu;
    uint32_t vco = 8000000u / m * n;
    printf("%u %u\n", (unsigned)(vco / p), (unsigned)(vco / q));
    return 0;
}
```

The FPU's coprocessors CP10 and CP11 are controlled by bits 23:20 of CPACR, in the System Control Space. Which hex digit completes the line so both get full access?

```c
#include <stdint.h>
#define CPACR (*(volatile uint32_t *)0xE000ED88u)
void fpu_enable(void) {
    CPACR |= (0x?u << 20);
    __asm volatile("dsb\n isb");
}
```

In a fictional timer, status register `TMR_FLAGS` has two flags, bit 0 (OVF) and bit 1 (CMP), both w1c. Starting each time with both flags set, which flags are still set after each function?

```c
#include <stdint.h>
#define TMR_FLAGS (*(volatile uint32_t *)0x4000A004u)
void clear_a(void) { TMR_FLAGS |= 1u; }
void clear_b(void) { TMR_FLAGS = 1u; }
```

The STM32F407 datasheet's alternate-function table lists PA2 as AF7 = USART2_TX. In the reference manual, GPIOA_MODER uses 2 bits per pin (`00` input, `01` output, `10` alternate function, `11` analog) and the low alternate-function register AFRL (`AFR[0]` in ST's device header) uses 4 bits per pin for pins 0 to 7. Fill in the two blanks to route PA2 to USART2_TX.

```c
GPIOA->MODER = (GPIOA->MODER & ~(3u << 4)) | (__ << 4);
GPIOA->AFR[0] = (GPIOA->AFR[0] & ~(0xFu << 8)) | (__ << 8);
```
